    "home.install.sub": "एक बार छूने पर ऐप की तरह खुलता है",
    "sharelib.launch.title": "किसी भाषा का पुस्तकालय साझा करें",
    "sharelib.launch.lead": "एक भाषा चुनें, फिर ईमेल लिंक दबाएँ। आपका ईमेल ऐप सही लिंक के साथ खुल जाएगा।",
    "sharelib.launch.for": "लैरी के लिए",
    "sharelib.launch.back": "पूरे पुस्तकालय पर वापस जाएँ",
    "sharelib.launch.webnote": "ईमेल करने से पहले यह पृष्ठ BibleTransfer123 वेबसाइट से खोलें। कार्ड से खोला गया लिंक केवल इसी कंप्यूटर पर काम करता है।",
    "sharelib.launch.resources": "{n} सामग्री",
    "sharelib.launch.open": "पुस्तकालय खोलें",
    "item.read.full": "पूरा PDF खोलें",
    "item.read.original": "मूल स्कैन देखें (PDF)",
    "item.read.modern": "वाइक्लिफ़ को आधुनिक वर्तनी में पढ़ें (PDF)",
    "item.read.phone": "यह आपके फ़ोन के PDF रीडर में खुलेगा, ताकि आप स्क्रॉल और ज़ूम कर सकें।",
    "item.by": "{org} से",
    "item.openfile": "यह फ़ाइल खोलें",
