    "save.title": "फ़ोन में सहेजना",
    "save.tap": "नीचे का बटन दबाएँ। आपका फ़ोन पूछेगा कि फ़ाइल कहाँ रखनी है, या उसे सीधे डाउनलोड में रख देगा।",
