    "share.golden": "पहले एक छोटी फ़ाइल भेजें",
    "share.golden.body": "कुछ बड़ा भेजने से पहले एक PDF या एक ऑडियो फ़ाइल से जाँच करें। एक छोटी फ़ाइल चालीस मिनट की जगह दस सेकंड में बता देती है कि कनेक्शन टूटा है।",
    "share.teach": "अब उन्हें करने दें",
    "share.teach.body": "जिस व्यक्ति को आपने फ़ाइल भेजी, उससे कहें कि अभी आपके सामने वही फ़ाइल किसी और को भेजे। उसी पल यह उनकी अपनी हो जाती है।",
    "dev.iphone": "iPhone या iPad",
