    "share.howto.sub": "AirDrop, Quick Share, ਤਾਰ ਜਾਂ ਕਾਰਡ — ਕਿਸੇ ਵੀ ਦੋ ਯੰਤਰਾਂ ਲਈ",
    "nearby.lead": "ਦੋਵੇਂ ਫ਼ੋਨ ਇਹ ਪੰਨਾ ਖੋਲ੍ਹਣ। ਇੱਕ ਭੇਜਦਾ ਹੈ, ਇੱਕ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ। ਫ਼ਾਈਲ ਸਿੱਧੀ ਇੱਕ ਤੋਂ ਦੂਜੇ ਵਿੱਚ ਜਾਂਦੀ ਹੈ।",
    "nearby.send.sub": "ਫ਼ਾਈਲ ਮੇਰੇ ਕੋਲ ਹੈ",
