    "nearby.code.tell": "ਦੂਜੇ ਫ਼ੋਨ 'ਤੇ ਪ੍ਰਾਪਤ ਕਰੋ ਦਬਾਓ ਅਤੇ ਇਹ ਨੰਬਰ ਲਿਖੋ।",
    "nearby.enter": "ਦੂਜੇ ਫ਼ੋਨ 'ਤੇ ਦਿਸਦਾ ਨੰਬਰ ਲਿਖੋ",
