    "route.card-iphone.3.p": "ਫ਼ਾਈਲ ਦਬਾ ਕੇ ਰੱਖੋ, Copy ਦਬਾਓ, ਫਿਰ On My iPhone, Downloads ਵਿੱਚ ਜਾ ਕੇ Paste ਕਰੋ। ਜੇ ਸਿਰਫ਼ ਕਾਰਡ ਤੋਂ ਖੋਲ੍ਹਦੇ ਹੋ, ਤਾਂ ਕਾਰਡ ਕੱਢਦਿਆਂ ਹੀ ਇਹ ਗ਼ਾਇਬ ਹੋ ਜਾਂਦੀ ਹੈ।",
