    "route.card-android.2.h": "Files ਖੋਲ੍ਹ ਕੇ ਕਾਰਡ ਲੱਭੋ",
    "route.card-android.2.p": "ਕਾਰਡ SD card ਜਾਂ ਮਿਲਦੇ-ਜੁਲਦੇ ਨਾਂ ਨਾਲ ਦਿਸਦਾ ਹੈ, ਅੰਦਰੂਨੀ ਸਟੋਰੇਜ ਤੋਂ ਵੱਖ।",
    "route.card-android.3.h": "ਫ਼ੋਨ ਵਿੱਚ ਕਾਪੀ ਕਰੋ, ਸਿਰਫ਼ ਖੋਲ੍ਹੋ ਨਾ",
