    "route.card-computer.1.p": "ਜ਼ਿਆਦਾਤਰ ਲੈਪਟਾਪਾਂ ਨੂੰ USB ਅਡੈਪਟਰ ਚਾਹੀਦਾ ਹੈ; ਕੁਝ ਵਿੱਚ ਸਲਾਟ ਹੁੰਦਾ ਹੈ।",
    "route.card-computer.2.h": "ਕਾਰਡ ਖੋਲ੍ਹੋ",
