    "route.card-computer.3.h": "ਪੂਰਾ ਫ਼ੋਲਡਰ ਕਾਪੀ ਕਰੋ, ਟੁਕੜੇ ਨਹੀਂ",
    "route.card-computer.3.p": "ਜੇ ਲਾਇਬ੍ਰੇਰੀ ਦੀ ਨਕਲ ਬਣਾ ਰਹੇ ਹੋ, ਤਾਂ ਸਭ ਕੁਝ ਕਾਪੀ ਕਰੋ ਅਤੇ ਹਰ ਫ਼ੋਲਡਰ ਦਾ ਨਾਂ ਬਿਲਕੁਲ ਉਹੀ ਰੱਖੋ। ਐਪ ਆਪਣੀਆਂ ਫ਼ਾਈਲਾਂ ਰਾਹ ਤੋਂ ਲੱਭਦੀ ਹੈ, ਇਸ ਲਈ ਨਾਂ ਬਦਲਿਆ ਫ਼ੋਲਡਰ ਮਤਲਬ ਖ਼ਾਲੀ ਖੁੱਲ੍ਹਣ ਵਾਲੀ ਲਾਇਬ੍ਰੇਰੀ।",
    "route.card-computer.4.h": "ਠੀਕ ਤਰ੍ਹਾਂ ਕੱਢੋ",
    "route.card-computer.4.p": "ਕਾਰਡ ਕੱਢਣ ਤੋਂ ਪਹਿਲਾਂ Eject ਜਾਂ Safely Remove ਕਰੋ, ਨਹੀਂ ਤਾਂ ਕਾਪੀ ਚੁੱਪਚਾਪ ਅਧੂਰੀ ਰਹਿ ਸਕਦੀ ਹੈ।",
