    "route.computer-computer.1.h": "ਡਰਾਈਵ ਨਾਲ",
    "route.computer-computer.1.p": "ਪੂਰਾ ਲਾਇਬ੍ਰੇਰੀ ਫ਼ੋਲਡਰ USB ਸਟਿੱਕ 'ਤੇ ਕਾਪੀ ਕਰੋ, ਦੂਜੇ ਕੰਪਿਊਟਰ ਵਿੱਚ ਲਾਓ ਅਤੇ ਕਾਪੀ ਕਰ ਲਓ। ਫ਼ੋਲਡਰ ਦੀ ਬਣਤਰ ਉਹੀ ਰੱਖੋ।",
    "route.computer-computer.2.h": "ਨੈੱਟਵਰਕ ਨਾਲ",
    "route.computer-computer.2.p": "LocalSend Windows, Mac ਅਤੇ Linux 'ਤੇ ਚੱਲਦਾ ਹੈ ਅਤੇ ਇੱਕੋ ਨੈੱਟਵਰਕ 'ਤੇ ਬਿਨਾਂ ਖਾਤੇ ਅਤੇ ਬਿਨਾਂ ਇੰਟਰਨੈੱਟ ਫ਼ਾਈਲਾਂ ਭੇਜਦਾ ਹੈ।",
    "route.computer-computer.3.h": "ਆਕਾਰ ਮਿਲਾ ਕੇ ਵੇਖੋ",
    "route.computer-computer.3.p": "ਪੂਰਾ ਮੰਨਣ ਤੋਂ ਪਹਿਲਾਂ ਦੋਵਾਂ ਕੰਪਿਊਟਰਾਂ 'ਤੇ ਫ਼ੋਲਡਰ ਦਾ ਆਕਾਰ ਮਿਲਾਓ। ਵਿਚਕਾਰ ਰੁਕੀ ਕਾਪੀ ਤਦ ਤੱਕ ਪੂਰੀ ਲੱਗਦੀ ਹੈ ਜਦ ਤੱਕ ਕੋਈ ਅਧੂਰਾ ਹਿੱਸਾ ਨਾ ਖੋਲ੍ਹੇ।",
