    "route.computer-card.2.h": "ਪਹਿਲਾਂ ਨਵੇਂ ਕਾਰਡ ਨੂੰ ਫ਼ਾਰਮੈਟ ਕਰੋ",
    "route.computer-card.2.p": "32 GB ਤੋਂ ਵੱਡੇ ਕਾਰਡ ਲਈ exFAT, ਛੋਟੇ ਲਈ FAT32। ਫ਼ਾਰਮੈਟ ਕਰਨ ਨਾਲ ਕਾਰਡ ਮਿਟ ਜਾਂਦਾ ਹੈ — ਪੱਕਾ ਕਰੋ ਕਿ ਸਹੀ ਕਾਰਡ ਹੈ।",
    "route.computer-card.3.h": "ਸਭ ਕੁਝ ਕਾਪੀ ਕਰੋ",
