    "route.computer-card.4.p": "ਇਸਨੂੰ ਫ਼ੋਨ ਵਿੱਚ ਲਾਓ ਅਤੇ START-HERE.html ਖੋਲ੍ਹੋ। ਇੱਕ ਫ਼ਿਲਮ ਚਲਾਓ ਅਤੇ ਇੱਕ PDF ਖੋਲ੍ਹੋ। ਬਿਨਾਂ ਜਾਂਚਿਆ ਕਾਰਡ ਉਸੇ ਦੇ ਸਾਹਮਣੇ ਫ਼ੇਲ੍ਹ ਹੁੰਦਾ ਹੈ ਜਿਸਨੂੰ ਤੁਸੀਂ ਦਿੱਤਾ।",
