    "help.computer.3.h": "پوري لائبريري رکڻ لاءِ",
    "help.computer.3.p": "الڳ الڳ فائلون نه، پورو ڪارڊ ڪاپي ڪريو. هر فولڊر جو نالو بلڪل ساڳيو رکو.",
