    "route.iphone-iphone.name": "AirDrop（隔空投送）",
    "route.iphone-iphone.1.h": "两部手机都打开无线功能",
    "route.iphone-iphone.1.p": "在两部 iPhone 上打开控制中心，确认 Wi-Fi 和蓝牙都已打开。AirDrop 两者都要用，尽管都不需要联网。",
    "route.iphone-iphone.2.h": "设置接收方可以接收",
    "route.iphone-iphone.2.p": "在接收的 iPhone 上：设置、通用、隔空投送，选择“所有人（10 分钟）”。如果设成“仅限联系人”而你不在对方通讯录里，什么都不会出现，双方也不知道原因。",
    "route.iphone-iphone.3.h": "从“文件”应用分享",
