    "route.iphone-iphone.5.h": "分开之前打开看看",
    "route.iphone-iphone.5.p": "请对方现在就打开一次。没人打开过的文件，坏了也没人知道。",
    "route.android-android.name": "Quick Share 或 LocalSend",
    "route.android-android.1.h": "先试 Quick Share",
    "route.android-android.1.p": "在发送的手机上打开 Files，长按文件，点“分享”，再点 Quick Share。在接收的手机上下拉快捷设置，打开 Quick Share 让它可见。",
    "route.android-android.2.h": "没有 Quick Share 就用 LocalSend",
    "route.android-android.2.p": "有些 Android 手机没有它。LocalSend 作用相同，可在同一 Wi-Fi 下任意两部手机间使用，无需账号。趁还有信号时在两部手机上都装好 — 如果套件里有，存储卡上也有。",
    "route.android-android.3.h": "两部手机连同一个网络",
    "route.android-android.3.p": "VillageServer 的 Wi-Fi 就够了。不需要互联网 — 两部手机只要能互相看到就行。",
    "route.android-android.4.h": "发送，然后接受",
    "route.android-android.4.p": "在发送方选好文件，从列表中选另一部手机，再在接收方点接受。",
    "route.android-android.5.h": "看看文件到了哪里",
    "route.android-android.5.p": "打开 Files，然后 Downloads，把文件打开一次。",
    "route.iphone-android.name": "LocalSend，或中间用一台电脑",
    "route.iphone-android.1.h": "先了解为什么这个比较难",
    "route.iphone-android.1.p": "AirDrop 只和苹果设备通信，Quick Share 只和 Android 通信。两者之间需要能同时和两边通信的东西。",
    "route.iphone-android.2.h": "最好：两边都装 LocalSend",
    "route.iphone-android.2.p": "在 iPhone 和 Android 手机上都安装 LocalSend，连同一个 Wi-Fi — VillageServer 网络就可以 — 然后发送。无需互联网，无需账号。",
    "route.iphone-android.3.h": "如果什么都装不了",
    "route.iphone-android.3.p": "把 iPhone 接到电脑上复制出文件，再接上 Android 复制过去。慢一些，但不用下载任何东西。",
    "route.iphone-android.4.h": "或者直接用存储卡",
    "route.iphone-android.4.p": "在有卡槽或转接器的手机上，把文件放到 microSD 卡里，然后拿走这张卡。完全没有网络时，这是最可靠的办法。",
    "route.iphone-android.5.h": "用一个小文件测试",
    "route.iphone-android.5.p": "不管选哪种方法，先发一个 PDF，确认能打开。",
    "route.computer-iphone.name": "用数据线，通过访达或 iTunes",
    "route.computer-iphone.1.h": "接上手机",
