    "route.computer-android.name": "用数据线，文件传输模式",
    "route.computer-android.1.h": "接上手机",
    "route.computer-android.1.p": "用数据线，不要用只能充电的线。",
    "route.computer-android.2.h": "把手机切换到文件传输",
    "route.computer-android.2.p": "Android 默认只充电。下拉写着“正在通过 USB 为此设备充电”的通知，点它，选择“文件传输”。不这样做，电脑什么都看不到，看起来像线坏了。",
    "route.computer-android.3.h": "在电脑上打开手机",
