    "nearby.bad": "號碼唔啱。請核對再試。",
    "nearby.offline": "呢個要經 Wi-Fi 或者互聯網打開呢一頁。直接由記憶卡打開，兩部手機搵唔到對方 — 請改用逐步指南。",
    "nearby.teach": "而家等佢哋自己做：叫佢哋而家就喺你面前轉傳俾第二個人。",
