    "nearby.accept.folder": "接受並揀資料夾",
    "nearby.declined": "{device}拒絕咗。",
    "ui.theme": "淺色或深色",
    "route.iphone-iphone.name": "AirDrop（隔空投送）",
    "route.iphone-iphone.1.h": "兩部都開無線功能",
    "route.iphone-iphone.1.p": "喺兩部 iPhone 打開控制中心，確認 Wi-Fi 同藍牙都開咗。AirDrop 兩樣都要用，雖然都唔使上網。",
    "route.iphone-iphone.2.h": "設定接收嗰部可以收",
    "route.iphone-iphone.2.p": "喺接收嘅 iPhone：設定、一般、隔空投送，揀「所有人（10 分鐘）」。如果設咗「只限聯絡人」而你唔喺對方通訊錄，乜都唔會出現，兩個都唔知點解。",
    "route.iphone-iphone.3.h": "由「檔案」App 分享",
    "route.iphone-iphone.3.p": "喺傳送嘅 iPhone 打開「檔案」，搵到儲存咗嘅檔案，長按，撳「分享」，再喺隔空投送嗰行撳對方。",
    "route.iphone-iphone.4.h": "喺另一部手機接受",
    "route.iphone-iphone.4.p": "接收嘅人撳「接受」。檔案會去「檔案」App 嘅 Downloads 入面。",
    "route.iphone-iphone.5.h": "分開之前打開睇吓",
    "route.iphone-iphone.5.p": "叫對方而家打開一次。冇人打開過嘅檔案，壞咗都冇人知。",
    "route.android-android.name": "Quick Share 或 LocalSend",
    "route.android-android.1.h": "先試 Quick Share",
    "route.android-android.1.p": "喺傳送嘅手機打開 Files，長按檔案，撳「分享」，再撳 Quick Share。喺接收嘅手機拉低快速設定，開啟 Quick Share 等佢睇得到。",
    "route.android-android.2.h": "冇 Quick Share 就用 LocalSend",
    "route.android-android.2.p": "有啲 Android 手機冇呢樣。LocalSend 做到同一樣嘢，喺同一個 Wi-Fi 任何兩部手機之間都用得，唔使戶口。趁仲有訊號喺兩部手機都裝好 — 如果套裝有，記憶卡上面都有。",
    "route.android-android.3.h": "兩部手機連同一個網絡",
    "route.android-android.3.p": "VillageServer 嘅 Wi-Fi 已經夠。唔使上網 — 兩部手機只要睇到對方就得。",
    "route.android-android.4.h": "傳送，再接受",
    "route.android-android.4.p": "喺傳送嗰部揀檔案，由清單揀另一部手機，再喺接收嗰部撳接受。",
    "route.android-android.5.h": "睇吓個檔案去咗邊",
    "route.android-android.5.p": "打開 Files，再入 Downloads，將個檔案打開一次。",
    "route.iphone-android.name": "LocalSend，或者中間用一部電腦",
    "route.iphone-android.1.h": "明白點解呢個難啲",
    "route.iphone-android.1.p": "AirDrop 只同 Apple 裝置溝通，Quick Share 只同 Android 溝通。兩者之間要有一樣同兩邊都講到嘢嘅嘢。",
    "route.iphone-android.2.h": "最好：兩邊都裝 LocalSend",
    "route.iphone-android.2.p": "喺 iPhone 同 Android 手機都裝 LocalSend，連同一個 Wi-Fi — VillageServer 網絡都得 — 然後傳送。唔使上網，唔使戶口。",
    "route.iphone-android.3.h": "如果乜都裝唔到",
    "route.iphone-android.3.p": "將 iPhone 駁電腦抄個檔案出嚟，再駁 Android 抄入去。慢啲，但唔使下載任何嘢。",
    "route.iphone-android.4.h": "或者直接用記憶卡",
    "route.iphone-android.4.p": "喺有卡槽或者轉接器嘅手機，將檔案放入 microSD 卡，再攞走張卡。完全冇網絡嘅時候，呢個係最可靠嘅方法。",
    "route.iphone-android.5.h": "用一個細檔案測試",
    "route.iphone-android.5.p": "無論揀邊個方法，先傳一個 PDF，確認打得開。",
    "route.computer-iphone.name": "用線，經 Finder 或 iTunes",
    "route.computer-iphone.1.h": "駁好部手機",
    "route.computer-iphone.1.p": "用傳到資料嘅線。好多叉電線傳唔到資料，但睇落一樣 — 如果電腦一直唔顯示部手機，第一時間換條線先。",
    "route.computer-iphone.2.h": "信任呢部電腦",
    "route.computer-iphone.2.p": "iPhone 會問「要信任這部電腦嗎？」。撳「信任」再輸入密碼，唔係乜都睇唔到。",
    "route.computer-iphone.3.h": "喺電腦打開",
    "route.computer-iphone.3.p": "Mac 打開 Finder，喺側邊欄揀 iPhone。Windows 打開 iTunes。",
    "route.computer-iphone.4.h": "將檔案拖過去",
    "route.computer-iphone.4.p": "喺「檔案」分頁將檔案拖去讀到佢嘅 App，或者拖入「檔案」App 嘅範圍。",
    "route.computer-iphone.5.h": "喺手機搵到佢",
    "route.computer-iphone.5.p": "喺 iPhone 打開「檔案」App，確認檔案喺度而且打得開。",
    "route.computer-android.name": "用線，檔案傳輸模式",
    "route.computer-android.1.h": "駁好部手機",
    "route.computer-android.1.p": "用資料線，唔好用淨係叉電嘅線。",
    "route.computer-android.2.h": "將手機轉去檔案傳輸",
    "route.computer-android.2.p": "Android 預設淨係叉電。拉低寫住「正在透過 USB 為此裝置充電」嘅通知，撳佢，揀「檔案傳輸」。唔咁做，電腦乜都睇唔到，好似條線壞咗咁。",
    "route.computer-android.3.h": "喺電腦打開部手機",
    "route.computer-android.3.p": "Windows：會喺檔案總管以手機名稱出現。Mac：先裝 Android File Transfer，再打開。",
    "route.computer-android.4.h": "抄入 Download",
    "route.computer-android.4.p": "將檔案放入手機嘅 Download 資料夾，咁佢就會喺對方會去搵嘅地方。",
    "route.computer-android.5.h": "喺手機確認",
    "route.computer-android.5.p": "打開 Files，再入 Downloads，將個檔案打開一次。",
    "route.card-iphone.name": "讀卡器插入 Lightning 或 USB-C 插口",
    "route.card-iphone.1.h": "你需要一個讀卡器",
    "route.card-iphone.1.p": "iPhone 冇卡槽。要一個插得入手機插口嘅 microSD 讀卡器 — 舊款 iPhone 係 Lightning，新款係 USB-C。出發前確認係邊款。",
    "route.card-iphone.2.h": "卡入讀卡器，讀卡器入手機",
    "route.card-iphone.2.p": "「檔案」App 會喺側邊欄將張卡顯示做一個新位置。",
