    "route.card-iphone.3.p": "長按檔案，撳「拷貝」，再去「我的 iPhone」、Downloads，撳「貼上」。如果淨係喺張卡打開，一拔走張卡檔案就冇咗。",
    "route.card-iphone.4.h": "拔走張卡再檢查",
    "route.card-iphone.4.p": "拔走讀卡器，再由「我的 iPhone」打開檔案。仲打得開，就真係喺手機度。",
    "route.card-android.name": "直接插入卡槽",
    "route.card-android.1.h": "搵個卡槽",
    "route.card-android.1.p": "好多 Android 手機可以直接插 microSD 卡，通常喺 SIM 卡托度。如果你部唔得，USB-C 讀卡器都做到。",
    "route.card-android.2.h": "打開 Files 搵張卡",
